import { BUILDINGS, CODES, WARDS, WARD_PREFIXES } from "./postal-tokyo23";

/**
 * Postal-code lookup over Japan Post's data for Tokyo's 23 wards (PRD 2.3), the only area we deliver to (D20).
 * The table is generated by scripts/postal-tokyo23.mjs; small enough to ship to the browser so lookups are instant.
 */
export interface PostalHit {
  prefecture: string;
  city: string;
  town: string;
  wardEn: string;
  /** JIS municipality code, e.g. 13110 = Meguro-ku; the 23-ward check runs on this (D20). */
  wardCode: string;
  /** true when we deliver there. Every hit is in the 23 wards; a per-ward allow list in Settings (D20) would narrow this. */
  deliverable: boolean;
}

export function normalisePostal(input: string): string {
  return input.replace(/[^0-9０-９]/g, "").replace(/[０-９]/g, (c) => String.fromCharCode(c.charCodeAt(0) - 0xfee0));
}

/** Whether a two-digit floor suffix is in a building's assigned ranges ("01-37,90"). */
function assigned(ranges: string, suffix: number): boolean {
  return ranges.split(",").some((r) => {
    const [from, to = from] = r.split("-").map(Number);
    return suffix >= from && suffix <= to;
  });
}

export function lookupPostal(input: string): PostalHit | null {
  const key = normalisePostal(input);
  if (key.length !== 7) return null;
  // Skyscrapers have a code per floor under the building's first five digits; only the floors Japan Post assigned exist.
  const building = BUILDINGS[key.slice(0, 5)];
  const found = CODES[key] ?? (building && assigned(building[2], Number(key.slice(5))) ? building : undefined);
  if (!found) return null;
  const [wardCode, city, wardEn] = WARDS[found[0]];
  return { prefecture: "東京都", city, town: found[1], wardEn, wardCode, deliverable: true };
}

/**
 * A 7-digit code whose first three digits (its delivery area) never occur in the 23 wards: wherever it is,
 * we don't deliver there, so say that rather than "not found". Codes in a ward area that miss the table are typos.
 */
export function outsideWards(input: string): boolean {
  const key = normalisePostal(input);
  return key.length === 7 && !WARD_PREFIXES.has(key.slice(0, 3));
}
